import static org.junit.jupiter.api.Assertions.assertTrue;

class ComputeTests {

    private EvalContext rootContext;
    private Step[] steps;

    @BeforeEach
    void setUp() {
        Object bean = new Object();
        JXPathContext jxpathContext = JXPathContext.newContext(bean);

        NodePointer rootPointer = NodePointer.newNodePointer(null, bean, jxpathContext.getLocale());
        rootContext = new RootContext(jxpathContext, rootPointer);

        Step step = new Step(Compiler.AXIS_CHILD, new NameTest(new QName("test")), null);
        steps = new Step[]{step};
    }

    @Test
    void testComputeWithAbsoluteLocationPathAndSteps() {
        LocationPath absolutePath = new LocationPath(true, steps);
        Object result = absolutePath.compute(rootContext);

        assertNotNull(result);
        assertTrue(result instanceof EvalContext);
    }

    @Test
    void testComputeWithRelativeLocationPathAndSteps() {
        LocationPath relativePath = new LocationPath(false, steps);
        Object result = relativePath.compute(rootContext);

