        // If we pass arbitrary nodes, the parent check inside compareChildNodePointers logic relies on 'this.node' (the parent).

        assertThrows(IllegalStateException.class, () -> {
            nonElementParentPointer.compareChildNodePointers(pointer1, pointer2);
        });
    }

