        // Read 4: 'E' (bufpos 4)
        // Read 5: 'F' (bufpos wraps to 0, buffer[0] becomes 'F')
        // State: bufpos 0. Buffer: ['F', 'B', 'C', 'D', 'E'].

        for (int i = 0; i < 6; i++) {
            stream.readChar();
        }

