import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.net.URL;

import org.apache.commons.jxpath.JXPathException;
import org.junit.jupiter.api.Test;

public class ParseXMLTests {

    @Test
    public void testParseXMLWithDOMModel() throws Exception {
        URL url = new URL("http://localhost/dummy.xml");
        DocumentContainer container = new DocumentContainer(url, DocumentContainer.MODEL_DOM);
        String xmlContent = "<root><child>content</child></root>";
        InputStream stream = new ByteArrayInputStream(xmlContent.getBytes());

        Object result = container.parseXML(stream);

        assertNotNull(result);
        assertTrue(result instanceof org.w3c.dom.Node);
    }

    @Test
    public void testParseXMLWithJDOMModel() throws Exception {
        URL url = new URL("http://localhost/dummy.xml");
        DocumentContainer container = new DocumentContainer(url, DocumentContainer.MODEL_JDOM);
        String xmlContent = "<root><child>content</child></root>";
        InputStream stream = new ByteArrayInputStream(xmlContent.getBytes());

        Object result = container.parseXML(stream);

        assertNotNull(result);
    }

    @Test
    public void testParseXMLWithNullStreamThrowsException() throws Exception {
        URL url = new URL("http://localhost/dummy.xml");
        DocumentContainer container = new DocumentContainer(url, DocumentContainer.MODEL_DOM);

        assertThrows(JXPathException.class, () -> {
            container.parseXML(null);
        });
    }

    @Test
    public void testParseXMLWithMalformedXmlThrowsException() throws Exception {
        URL url = new URL("http://localhost/dummy.xml");
        DocumentContainer container = new DocumentContainer(url, DocumentContainer.MODEL_DOM);
        String malformedXml = "<root><child>";
        InputStream stream = new ByteArrayInputStream(malformedXml.getBytes());

        assertThrows(JXPathException.class, () -> {
            container.parseXML(stream);
        });
    }

    @Test
    public void testConstructorWithNullUrlThrowsException() {
        assertThrows(JXPathException.class, () -> {
            new DocumentContainer(null);
        });
    }
}

