        // multipleMatch(Integer, String) is convertible (int -> Integer).
        // Expect exact match to be returned, no exception.
        Object[] args = {1, "test"};
        Method method = MethodLookupUtils.lookupStaticMethod(TargetClass.class, "multipleMatch", args);

        assertNotNull(method);
