        // We verify the lookup mechanism handles the conversion.
        Object[] args = {1, "test"};
        Method method = MethodLookupUtils.lookupStaticMethod(TargetClass.class, "convertibleMatch", args);

        assertNotNull(method);
        assertEquals(Integer.class, method.getParameterTypes()[0]);
